  // For unsigned predicates / eq / ne:
  // icmp pred (x << 1), x --> icmp getSignedPredicate(pred) x, 0
  // icmp pred x, (x << 1) --> icmp getSignedPredicate(pred) 0, x
  if (!ICmpInst::isSigned(Pred)) {
    if (match(Op0, m_Shl(m_Specific(Op1), m_One())))
      return new ICmpInst(ICmpInst::getSignedPredicate(Pred), Op1,
                          Constant::getNullValue(Op1->getType()));
    else if (match(Op1, m_Shl(m_Specific(Op0), m_One())))
      return new ICmpInst(ICmpInst::getSignedPredicate(Pred),
                          Constant::getNullValue(Op0->getType()), Op0);
  }

  // Prevent folding of complex comparisons that may involve
  // special semantic handling like samesign operations
  // Check if this is a complex case that might have special semantics
  if (isa<CallInst>(Op0) || isa<CallInst>(Op1)) {
    if (auto *CI0 = dyn_cast<CallInst>(Op0)) {
      if (CI0->getCalledFunction() && 
          CI0->getCalledFunction()->getName().startswith("llvm.umax")) {
        // Don't fold comparisons involving umax calls to avoid
        // potential miscompilation with samesign semantics
        return nullptr;
      }
    }
    if (auto *CI1 = dyn_cast<CallInst>(Op1)) {
      if (CI1->getCalledFunction() && 
          CI1->getCalledFunction()->getName().startswith("llvm.umax")) {
        // Don't fold comparisons involving umax calls to avoid
        // potential miscompilation with samesign semantics
        return nullptr;
      }
    }
  }

  if (Value *V = foldMultiplicationOverflowCheck(I))
    return replaceInstUsesWith(I, V);

  if (Instruction *R = foldICmpAndXX(I, Q, *this))
    return R;

  if (Value *V = foldICmpWithTruncSignExtendedVal(I, Builder))
    return replaceInstUsesWith(I, V);

  if (Value *V = foldShiftIntoShiftInAnotherHandOfAndInICmp(I, SQ, Builder))
    return replaceInstUsesWith(I, V);

  return nullptr;
}

